\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Dark Developer Palette ──
\definecolor{primary}{HTML}{0F172A}      % deep navy
\definecolor{secondary}{HTML}{1E293B}     % slate dark
\definecolor{accent}{HTML}{3B82F6}        % electric blue
\definecolor{amber}{HTML}{F59E0B}        % amber
\definecolor{mint}{HTML}{10B981}          % mint green
\definecolor{electric}{HTML}{8B5CF6}     % purple
\definecolor{bgposter}{HTML}{0F172A}      % poster background
\definecolor{cardbg}{HTML}{1E293B}        % card background
\definecolor{cardbg2}{HTML}{0F172A}      % darker card
\definecolor{textlight}{HTML}{F1F5F9}    % light text
\definecolor{textmuted}{HTML}{94A3B8}     % muted text
\definecolor{stathighlight}{HTML}{1E3A8A}

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{22}{28}\selectfont\color{textmuted}\textit{#3}}\vspace{2mm}%
}

% ── Card styles ──
\tcbset{
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardbg2,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.3},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{amber},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=cardbg2,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={amber!50},
    valign=top, drop shadow={opacity=0.3},
  },
  mintcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{mint},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{mint},
    coltitle=mint, colbacktitle=cardbg2,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={mint!50},
    valign=top, drop shadow={opacity=0.3},
  },
  purplecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{electric},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{electric},
    coltitle=electric, colbacktitle=cardbg2,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={electric!50},
    valign=top, drop shadow={opacity=0.3},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=accent!20!cardbg,
    borderline west={6pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{textlight},
    coltitle=textlight, colbacktitle=accent,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.3},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textlight,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.4}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries STATE OF DEVELOPER ECOSYSTEM 2024}\\[10pt]
  {\fontsize{30}{36}\selectfont\color{textmuted} Language Wars \& Rising Stars}\\[8pt]
  {\fontsize{24}{30}\selectfont\color{accent} 23,262 Developers Worldwide $\cdot$ JetBrains Survey}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=secondary, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=4pt, bottom=4pt,
  valign=center, borderline south={3pt}{0pt}{accent!40},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight!30}{\parbox{0.9\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{accent} 61\%}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textlight} JavaScript}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textmuted} Most Used}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{mint!50}{stathighlight!30}{\parbox{0.9\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{mint} 57\%}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textlight} Python}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textmuted} Rising Fast}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{electric!50}{stathighlight!30}{\parbox{0.9\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{electric} 37\%}\\[3pt]
      {\fontsize{22}{28}\selectfont\color{textlight} TypeScript}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{textmuted} +25pts since 2017}\vspace{4pt}%
    }}
  \end{minipage}
}

% ══ LANGUAGE TRAJECTORY CHART (CENTRAL) ══
\posterbox[darkcard, title={Programming Language Trajectory: 2017--2024}
]{name=langchart, column=1, span=2, between=row6 and row13}{
  \fontsize{28}{36}\selectfont
  \begin{center}
  \begin{tabular}{l|c|c|c|c|c|p{80mm}}
  \rowcolor{accent!20}
  \textbf{Language} & \textbf{2017} & \textbf{2019} & \textbf{2021} & \textbf{2023} & \textbf{2024} & \textbf{Trend} \\\hline
  JavaScript & 65\% & 69\% & 69\% & 61\% & 61\% & \cellcolor{accent!15}{\color{accent}Plateau} \\
  Python & 32\% & 49\% & 52\% & 54\% & 57\% & \cellcolor{mint!20}{\color{mint}$\uparrow$ Climb} \\
  HTML/CSS & 60\% & 61\% & 60\% & 52\% & 51\% & \cellcolor{textmuted!20}{\color{textmuted}$\downarrow$ Decline} \\
  TypeScript & 12\% & 25\% & 29\% & 34\% & 37\% & \cellcolor{electric!20}{\color{electric}$\uparrow\uparrow$ Surge} \\
  SQL & 42\% & 56\% & 54\% & 52\% & 48\% & \cellcolor{textmuted!15}{\color{textmuted}$\rightarrow$ Stable} \\
  Java & 47\% & 50\% & 49\% & 49\% & 46\% & \cellcolor{textmuted!15}{\color{textmuted}$\downarrow$ Fall} \\
  Rust & — & 6\% & 8\% & 7\% & 8\% & \cellcolor{amber!20}{\color{amber}ATH} \\
  Go & 17\% & 20\% & 23\% & 18\% & 17\% & \cellcolor{textmuted!15}{\color{textmuted}$\rightarrow$ Stable} \\
  \end{tabular}
  \end{center}
  \vspace{4pt}
  {\fontsize{20}{26}\selectfont\color{textmuted}\textit{Python: 32\% $\rightarrow$ 57\% (8yr climb). TypeScript: 12\% $\rightarrow$ 37\% (explosive growth).}}
}

% ══ PROMISE INDEX CALLOUT ══
\posterbox[ambercard, title={Language Promise Index 2024}
]{name=promise, column=3, between=row6 and row10}{
  \fontsize{28}{36}\selectfont
  \colorbox{amber!15}{\parbox{0.92\linewidth}{%
    {\fontsize{52}{64}\selectfont\bfseries\color{amber} 199} \\[4pt]
    {\fontsize{24}{30}\selectfont\color{textlight} TypeScript Score} \\[6pt]
    {\fontsize{18}{24}\selectfont\color{textmuted} Highest among all languages} %
  }}\\[8pt]
  \begin{enumerate}[itemsep=8pt]
    \item \color{amber}\textbf{TypeScript} -- 199
    \item \color{amber}\textbf{Rust} -- 198
    \item \color{mint}\textbf{Python} -- 151
    \item \color{textlight}\textbf{Go} -- 129
    \item \color{electric}\textbf{Lua} -- 118
    \item \color{textlight}\textbf{C++} -- 113
  \end{enumerate}
  \vspace{4pt}
  {\fontsize{18}{24}\selectfont\color{textmuted}\textit{Based on growth, stability, intent to adopt, retention}}
}

% ══ DATABASE SECTION ══
\posterbox[mintcard, title={Database Landscape}
]{name=databases, column=3, between=row10 and row14}{
  \fontsize{26}{34}\selectfont
  \begin{center}
  \begin{tabular}{l|c|c|c}
  \rowcolor{mint!20}
  \textbf{DB} & \textbf{2019} & \textbf{2022} & \textbf{2024} \\\hline
  MySQL & 60\% & 52\% & 52\% \\
  PostgreSQL & 32\% & 38\% & \cellcolor{mint!25}{\color{mint}\textbf{45\%}} \\
  MongoDB & 30\% & 27\% & 30\% \\
  SQLite & 29\% & 27\% & 30\% \\
  Redis & 22\% & 18\% & 20\% \\
  \end{tabular}
  \end{center}
  \vspace{6pt}
  \colorbox{mint!15}{\parbox{0.92\linewidth}{%
    {\fontsize{22}{28}\selectfont\color{mint}\textbf{PostgreSQL: +13pts}} \\[3pt]
    {\fontsize{18}{24}\selectfont\color{textmuted} 32\% $\rightarrow$ 45\% since 2019} %
  }}
}

% ══ CLOUD PLATFORMS ══
\posterbox[purplecard, title={Cloud Platforms}
]{name=cloud, column=1, between=row13 and row16}{
  \fontsize{28}{36}\selectfont
  \begin{minipage}[t]{0.45\linewidth}
    \colorbox{electric!15}{\parbox{0.92\linewidth}{%
      {\fontsize{44}{54}\selectfont\bfseries\color{electric} 46\%} \\[4pt]
      {\fontsize{22}{28}\selectfont\color{textlight} AWS} \\[3pt]
      {\fontsize{16}{20}\selectfont\color{textmuted} Still leads, down from 51\%}
    }}\\[6pt]
  \end{minipage}\hfill
  \begin{minipage}[t]{0.45\linewidth}
    \colorbox{accent!15}{\parbox{0.92\linewidth}{%
      {\fontsize{44}{54}\selectfont\bfseries\color{accent} 17\%} \\[4pt]
      {\fontsize{22}{28}\selectfont\color{textlight} Azure} \\[3pt]
      {\fontsize{16}{20}\selectfont\color{textmuted} Gaining ground}
    }}\\[6pt]
  \end{minipage}
}

% ══ PLATFORM SPLIT ══
\posterbox[darkcard, title={Where Applications Run}
]{name=platforms, column=2, between=row13 and row16}{
  \fontsize{28}{36}\selectfont
  \begin{center}
  \begin{tabular}{r|c}
  \rowcolor{accent!20}
  \textbf{Platform} & \textbf{Usage} \\\hline
  Browser & \cellcolor{accent!25}{\color{accent}\textbf{58\%}} \\
  Server/Cloud & \cellcolor{mint!20}{\color{mint}\textbf{56\%}} \\
  Desktop & \cellcolor{amber!20}{\color{amber}\textbf{53\%}} \\
  Mobile & \cellcolor{electric!20}{\color{electric}30\%} \\
  \end{tabular}
  \end{center}
  \vspace{4pt}
  {\fontsize{18}{24}\selectfont\color{textmuted}\textit{Desktop (53\%) > Mobile (30\%)}}
}

% ══ AI INTEGRATION SPOTLIGHT ══
\posterbox[highlightcard, title={AI in the Developer Workflow}
]{name=ai, column=3, span=2, between=row14 and row17}{
  \fontsize{30}{38}\selectfont
  \begin{minipage}[c]{0.28\linewidth}\centering
    \colorbox{accent!25}{\parbox{0.9\linewidth}{%
      {\fontsize{48}{58}\selectfont\bfseries\color{accent} 18\%} \\[3pt]
      {\fontsize{20}{26}\selectfont\color{textlight} of devs} \\[2pt]
      {\fontsize{16}{20}\selectfont\color{textmuted} build AI integrations}
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.35\linewidth}
    \begin{itemize}[itemsep=6pt]
      \item \color{mint}\textbf{Python} dominates AI/ML work
      \item \color{electric}\textbf{31\%} of Python devs do AI work
      \item \color{amber}\textbf{11\%} of C++ devs also in AI
      \item Fear of AI diminishing year over year
    \end{itemize}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.28\linewidth}
    \colorbox{amber!20}{\parbox{0.9\linewidth}{%
      {\fontsize{48}{58}\selectfont\bfseries\color{amber} 49\%} \\[3pt]
      {\fontsize{20}{26}\selectfont\color{textlight} use Docker} \\[2pt]
      {\fontsize{16}{20}\selectfont\color{textmuted} locally}
    }}
  \end{minipage}
}

% ══ KEY INSIGHTS FOOTER ══
\posterbox[darkcard, title={Key Insights}
]{name=insights, column=1, span=3, between=row17 and row20}{
  \fontsize{26}{34}\selectfont
  \begin{minipage}[c]{0.24\linewidth}\centering
    \colorbox{accent!20}{\parbox{0.95\linewidth}{%
      {\fontsize{20}{26}\selectfont\color{accent}$\blacktriangleright$} {\fontsize{20}{26}\selectfont\color{textlight} JS plateau, Python closing in}
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \colorbox{electric!20}{\parbox{0.95\linewidth}{%
      {\fontsize{20}{26}\selectfont\color{electric}$\blacktriangleright$} {\fontsize{20}{26}\selectfont\color{textlight} TypeScript: ecosystem signal}
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \colorbox{mint!20}{\parbox{0.95\linewidth}{%
      {\fontsize{20}{26}\selectfont\color{mint}$\blacktriangleright$} {\fontsize{20}{26}\selectfont\color{textlight} PostgreSQL surging past MySQL}
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \colorbox{amber!20}{\parbox{0.95\linewidth}{%
      {\fontsize{20}{26}\selectfont\color{amber}$\blacktriangleright$} {\fontsize{20}{26}\selectfont\color{textlight} AI integration: 1 in 5 devs}
    }}
  \end{minipage}
}

\end{tcbposter}
\end{document}

